Definition rs_ec (iseof : bool) : ecv := if iseof then EC_ts_eof_a else EC_clear.

Definition rs_cmp_post (sp gp tp t0 t1 t2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (E fb tot k genid : Z) (iseof : bool) (m : mem) : machine_state -> Prop :=
  fun ms' => (exists a0 a1 a2,
       ms' = if iseof
             then MS (mkR (Z_to_bv 64 RS_CMP) (Z_to_bv 64 (bv_unsigned sp + -208)) gp tp t0 t1 t2 (wz (E + 8)) (wz E)
                          (wz AG_MISC_CAT_INST) (wz (ALOC_TS_EOF + 1)) (wz 0) a3 a4 a5 a6 a7
                          (wz AG_MISC_CAT_INST) (wz (Z.shiftr (fb + 16) 3 + 2147450880)) (wz genid) (wz fb) (wz (Z.shiftr E 3 + 2147450880))
                          (wz (fb + 16)) (wz (fb + 8)) (wz k) (wz 2147450880) (wz (Z.shiftr (fb + 8) 3 + 2147450880)) t3 t4 t5 t6)
                     F (Z_to_bv 64 RS_EOF) fc None m (seg_rom asegs)
             else rs_ms RS_PARSE (Z_to_bv 64 RS_CMP) sp gp tp t0 t1 t2 (wz (E + 8)) E a0 a1 a2 a3 a4 a5 a6 a7 tot fb (wz (E + 8)) (wz (E + 16)) (wz k) t3 t4 t5 t6 F fc m)
    /\ munch [] m m /\ wmono asegs m m /\ mem_inv asegs m.
Scheme kc__1 := Elimination for Corelib.Init.Logic.and Sort Prop.
Scheme kc__2 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.

Lemma rs_cmp : forall sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo E bs fb P tot k genid : Z) (iseof : bool) (fbc t2c optc : list cell),
  rs_frame m sp E bs P (C8 (wz tot)) (C8 (wz (Z.shiftr (E + 16) 3 + 2147450880))) t2c optc ->
  rw_cells asegs m fb fbc -> cells_size fbc = 48%nat ->
  rw_cells asegs m E (ErrCodeCells (rs_ec iseof)) -> aapp E 24 -> accessible m E 24 -> E mod 8 = 0 ->
  AXStatics2 m -> 0 <= genid < 2^64 -> genid <> 0 ->
  0 <= bs < 2^64 -> 0 <= P < 2^64 -> 0 <= tot < 2^64 -> 0 <= k < 2^64 -> 0 <= fb -> fb + 48 < 2^64 ->
  mem_inv asegs m ->
  evt asegs (rs_cmp_post sp gp tp t0 t1 t2 a3 a4 a5 a6 a7 t3 t4 t5 t6 F fc E fb tot k genid iseof m)
    (MS (mkR (Z_to_bv 64 RS_CMP) (Z_to_bv 64 (bv_unsigned sp + -208)) gp tp t0 t1 t2 (wz (E + 8)) (wz E) a0 a1 a2 a3 a4 a5 a6 a7
             (wz AG_MISC_CAT_INST) (wz (Z.shiftr (fb + 16) 3 + 2147450880)) (wz genid) (wz fb) (wz (E + 16)) (wz (fb + 16)) (wz (fb + 8)) (wz k)
             (wz 2147450880) (wz (Z.shiftr (fb + 8) 3 + 2147450880)) t3 t4 t5 t6)
        F (Z_to_bv 64 RS_CMP) fc None m (seg_rom asegs)).
